const doorSides=['South','East','North','West'];
$('selectionCard').onclick=e=>{
 const b=e.target.closest('button');
 if(!b)return;
 if(b.dataset.worldRotate||b.dataset.worldRemove){
  const id=Number(b.dataset.worldRotate||b.dataset.worldRemove);
  const rotating=!!b.dataset.worldRotate;
  const result=rotating?rotateRoom(s,id):remove(s,id);
  if(!result.ok){toast(result.reason);return}
  paused=true;
  if(!rotating){selected=null;renderer.selected=null}
  renderer.syncRooms();
  save();
  renderUI();
  toast(rotating?'Room rotated. The door now faces '+doorSides[result.room.rotation].toLowerCase()+'.':'Room removed. Half its build cost was refunded.');
  return;
 }
if(b.dataset.worldFocus)renderer.focusRoom(+b.dataset.worldFocus);if(b.dataset.worldLift){const[kind,id]=b.dataset.worldLift.split(':');startHold(kind,+id)}if(b.dataset.worldInspect){const[kind,id]=b.dataset.worldInspect.split(':');select(kind,+id)}if(b.dataset.worldStaff){const result=staffRoom(+b.dataset.worldStaff);toast(result.ok?'The team is on its way.':result.reason);save();renderUI()}if(b.dataset.worldUpgrade)openEquipment(+b.dataset.worldUpgrade)};


