function showReport(){
 extras?.complete();const r=report(s),wait=r.waits.completed,types=s.clinic?Object.keys(CLINIC_DEPARTMENTS):['consult','scan','care',...(s.scenario==='community'?['plan']:[])],closing=types.map(type=>({type,n:s.patients.filter(p=>(p.intakeDone||s.clinic&&p.stage==='intake')&&p.stage===type&&['waiting','seated','queue-walking','seat-walking','seat-entering','handoff','signoff'].includes(p.state)).length})).sort((a,b)=>b.n-a.n)[0],used=[...s.records,...s.patients].filter(p=>p.history.some(h=>h.at>=(s.shiftStart||0)&&s.rooms.some(room=>room.id===h.room&&room.builtAt!==undefined))).length;
 const story=(used?used+' '+(used===1?'neighbor used':'neighbors used')+' your added rooms. ':'')+(closing.n?'At closing, '+closing.n+' were waiting for '+TYPES[closing.type].name.toLowerCase()+'. '+causes(s,closing.type).explanation:'The current service queues have breathing room.');
 modal(`<div class="eyebrow">${s.ended?'SHIFT COMPLETE':'YOUR SHIFT SO FAR'}</div><h2>${s.served} ${s.served===1?'neighbor':'neighbors'} home.${s.patients.length?'<br>'+s.patients.length+' still need help.':''}</h2><div class="report-grid"><div><b>${s.served}</b><small>home</small></div><div><b>${s.left}</b><small>left before completion</small></div><div><b>${s.patients.length}</b><small>still here</small></div></div><p class="shift-story">${story}</p>${s.ended?`<button id="nextShift" class="primary">${s.mode==='sandbox'&&s.seconds===shiftEnd(s)?'Next shift · keep hospital':s.mode==='campaign'&&mastery(s)?'Next scenario':'Try shift again'}</button><p>Your layout, colleagues, budget and unfinished visits stay with you in the continuing sandbox.</p>`:''}<p>Operating fund ${money(s.cash)} · team energy ${Math.round(s.energy)}%. ${s.periodCarried?s.periodCarried+' neighbors were carried into this shift.':''}</p><details><summary>Wait details &amp; shift report</summary><p>${s.arrivals} arrivals = ${s.served} completed + ${s.left} departed + ${s.patients.length} unfinished.</p><p>Completed visits (n=${wait.n}): mean ${wait.mean===null?'—':Math.round(wait.mean)+'s'}, median ${wait.median===null?'—':Math.round(wait.median)+'s'}, 90th percentile ${wait.p90===null?'—':wait.p90+'s'}. Waiting excludes walking, staffed check-in, active service, handoff, transfer and recovery. The mean omits long-waiting people who left and those still here; the export includes all arrivals, outcomes, timing definitions and cohort denominators.</p><p>${s.clinic?.checkedIn??s.operations.checkedIn} checked in; ${s.operations.intakeAssists} check-ins received assistant support. Results are fictional game outcomes. The experience indicator in JSON is unvalidated.</p><button id="exportReport">Export readable JSON</button><button id="labFromReport">Compare layouts</button></details><details><summary>Fresh layout &amp; recording</summary><button id="replay">Try a fresh layout</button><button id="recordMinute" ${s.ended?'disabled':''}>Record next minute</button><button id="recordVisit" ${s.ended?'disabled':''}>Record next 90 seconds</button><button id="recordLoop" ${s.ended?'disabled':''}>Record through shift end</button><p>Recording captures the actual3Dcanvas and state captions locally. HTML menus are summarized, not filmed; audio is not recorded.</p></details>`);
 if($('nextShift'))$('nextShift').onclick=nextShift;$('exportReport').onclick=()=>download(r,'common-good-shift.json');$('replay').onclick=()=>reset(s.scenario,s.mode);$('recordLoop').onclick=()=>recordLoop();$('recordMinute').onclick=()=>recordLoop(60);$('recordVisit').onclick=()=>recordLoop(90);$('labFromReport').onclick=()=>extras.lab();
}

