function frame(ts){const rawMs=last?ts-last:16.67,dt=Math.min(rawMs/1000,.1);last=ts;if(ready&&!paused&&!$('dialog').open&&!s.ended){acc+=dt*speed;while(acc>=1){tick(s);acc--;if(s.ended){paused=true;showReport();break}}if(s.seconds%5===0&&saveSecond!==s.seconds){saveSecond=s.seconds;save()}}if(ready&&renderer.onScreen&&!document.hidden&&!$('dialog').open){renderAcc+=dt;renderRaw+=rawMs;renderBudget+=dt;if(!renderer.mobile||renderBudget>=1/(held?60:30)){renderer.frame(Math.min(.1,renderAcc),paused?0:Math.min(.1,renderAcc)*speed,acc,paused,renderRaw);renderAcc=0;renderRaw=0;renderBudget%=1/(held?60:30)}}else{renderAcc=0;renderRaw=0;renderBudget=0}uiTimer+=dt;if(uiTimer>.5){uiTimer=0;renderUI()}requestAnimationFrame(frame)}
